function startUnionCrownEnding(){
 const c=beforeStoryScene,b=c?.unionCrown;if(!b||b.ending)return;
 stopBeforeStoryVoice();keys.clear();drag=false;document.exitPointerLock?.();b.ended=true;b.holding=false;b.chain=null;b.hand.visible=false;for(const link of b.chainLinks)link.visible=false;
 for(const effect of b.effects)disposeCampObject(effect.object);b.effects=[];
 if(b.attack){disposeCampObject(b.attack.ring);b.attack=null;}for(const p of b.projectiles)disposeCampObject(p.object);b.projectiles=[];
 b.enemy.position.set(.35,.32,-.1);b.enemy.rotation.set(0,0,Math.PI/2);b.enemy.userData.arms.forEach(arm=>arm.rotation.set(0,0,0));b.enemy.userData.legs.forEach(leg=>leg.rotation.set(0,0,0));
 b.hero.visible=true;b.hero.userData.unionCrownSpecter.visible=false;b.hero.rotation.set(0,-.15,0);
 b.hero.userData.mouth.visible=false;if(b.hero.userData.smileCrease)b.hero.userData.smileCrease.visible=false;
 const head=b.hero.userData.head,frown=line3(head,[[-.12,-.26,.302],[0,-.23,.331],[.12,-.26,.307]],mat(0x211017),.009);b.hero.userData.mouth=frown;
 head.children.forEach(o=>{if(o.geometry?.type==='TubeGeometry'){o.geometry.computeBoundingBox();const center=o.geometry.boundingBox.getCenter(new THREE.Vector3());if(center.y>.16&&center.y<.23&&Math.abs(center.x)>.08&&center.z>.25)o.visible=false;}});
 for(const side of [-1,1])line3(head,[[side*.07,.215,.31],[side*.16,.17,.31],[side*.24,.16,.286]],mat(0x30251f),.01);
 const tears=[];for(const side of [-1,1]){const tear=ball(head,.014,.075,.009,new THREE.MeshStandardMaterial({color:0xbad5e9,transparent:true,opacity:.5,roughness:.12}),side*.16,-.04,.326);tear.visible=false;tears.push(tear);}
 b.ending={line:0,time:0,beat:0,mouth:makeBeforeStorySpeechMouth('josiah',b.hero),tears,voiceFailed:false};
 unionFightUI.hidden=true;document.getElementById('unionModal').hidden=true;beforeStoryCinema.hidden=false;
 document.getElementById('beforeStoryCinemaChapter').textContent='BEFORE THE STORY / CHAPTER 4 / AFTERMATH';document.getElementById('beforeStoryCinemaTitle').innerHTML='UNION CROWN <span>WHAT HAVE I DONE?</span>';
 setMode('beforeStoryUnionEnding');world.visible=upperWorld.visible=exhibit.visible=flash.visible=false;scene.background.setHex(0x14111d);scene.fog.color.setHex(0x282430);scene.fog.density=.008;ambient.intensity=.85;cameraFill.intensity=.45;
 showUnionCrownEndingLine();renderUnionCrownEnding(0);updateMobileControls();
}
function showUnionCrownEndingLine(){
 const e=beforeStoryScene.unionCrown.ending;stopBeforeStoryVoice();e.beat=0;e.voiceFailed=false;e.speech=beforeStorySpeechTimeline(BEFORE_STORY_UNION_ENDING_LINES[e.line]);
 document.getElementById('beforeStorySpeaker').textContent='JOSIAH RICHARDS';document.getElementById('beforeStoryLine').textContent=BEFORE_STORY_UNION_ENDING_LINES[e.line];document.getElementById('beforeStoryCount').textContent=(e.line+1)+' / 10';document.getElementById('beforeStoryNext').hidden=false;document.getElementById('beforeStoryNext').textContent=e.line===9?'COMPLETE CHAPTER 4 →':'CONTINUE →';
 const clip=beforeStoryUnionEndingVoices[e.line];clip.muted=muted;clip.play()?.catch(()=>{if(beforeStoryScene?.unionCrown?.ending===e)e.voiceFailed=true;});
}
function advanceUnionCrownEnding(){
 const e=beforeStoryScene?.unionCrown?.ending;if(mode!=='beforeStoryUnionEnding'||!e)return;
 if(e.line===9){stopBeforeStoryVoice();beforeStoryProgress.unionCrownCompleted=true;saveBeforeStoryProgress();refreshBeforeStoryChapters();returnBeforeStoryRome();return;}
 e.line++;showUnionCrownEndingLine();
}
function unionCrownEndingVoiceLevel(){
 const e=beforeStoryScene.unionCrown.ending,clip=beforeStoryUnionEndingVoices[e.line];clip.muted=muted;
 if(e.voiceFailed||clip.error){const word=e.speech.words.find(w=>e.beat>=w.start&&e.beat<w.end);if(!word)return 0;const phase=(e.beat-word.start)/(word.end-word.start);return .6*Math.abs(Math.sin(phase*Math.PI*word.syllables));}
 if(clip.paused||clip.ended||clip.readyState<2)return 0;
 const data=BEFORE_STORY_UNION_ENDING_ENVELOPES[e.line],frame=clip.currentTime/data.step,index=Math.floor(frame),mix=frame-index;return (data.levels[index]||0)*(1-mix)+(data.levels[index+1]||0)*mix;
}
function renderUnionCrownEnding(dt){
 const c=beforeStoryScene,b=c?.unionCrown,e=b?.ending;if(!e)return;dt=Math.min(.05,Math.max(0,dt));e.time+=dt;e.beat+=dt;
 const u=b.hero.userData,kneel=THREE.MathUtils.smoothstep(e.time,2,4),tremble=Math.sin(e.time*15)*.004;
 b.hero.position.set(.8,-.52*kneel,.75);u.body.rotation.set(.04+Math.sin(e.time*2.5)*.007,0,tremble);u.head.rotation.set(.12+Math.sin(e.time*1.8)*.014,e.line===5?Math.sin(e.time*.7)*.3:-.08,-.035+tremble);
 for(let i=0;i<2;i++){u.legs[i].rotation.set(-kneel*(i?1.25:1.55),0,0);u.arms[i].rotation.set(e.line<3?-1.15:-.48,0,(i?1:-1)*.16);}
 const voice=unionCrownEndingVoiceLevel(),m=e.mouth;m.open.visible=voice>.035;m.open.scale.set(m.width*(1-.12*voice),.006+voice*.028,.009);m.closed.visible=!m.open.visible;if(u.smileCrease)u.smileCrease.visible=false;
 for(const tear of e.tears){tear.visible=e.line>=3;tear.position.y=-.04-Math.sin(e.time*.55)**2*.05;}
 camera.up.set(0,1,0);const wide=e.line<3;camera.position.copy(c.root.position).add(new THREE.Vector3(wide?2.8:1.8,wide?2.25:1.75,wide?4.5:3.25));camera.lookAt(c.root.position.clone().add(new THREE.Vector3(wide?.1:.7,wide?1.05:1.2,.35)));camera.updateMatrixWorld(true);
}

