function closeBokiCombatMouth(){const m=beforeStoryScene?.unionCrown?.enemyMouth;if(m){m.open.visible=false;m.closed.visible=true;}}
function stopBokiCombatVoice(){for(const clip of beforeStoryBokiCombatVoices){clip.pause();clip.currentTime=0;}const b=beforeStoryScene?.unionCrown;if(b){b.bokiVoiceIndex=null;b.bokiVoiceResume=false;}closeBokiCombatMouth();}
function pauseBokiCombatVoice(){const b=beforeStoryScene?.unionCrown;if(!b||b.successor)return;const clip=beforeStoryBokiCombatVoices[b.bokiVoiceIndex];b.bokiVoiceResume=!!clip&&!clip.paused&&!clip.ended;if(clip)clip.pause();closeBokiCombatMouth();}
function resumeBokiCombatVoice(){const b=beforeStoryScene?.unionCrown;if(!b||b.successor||!b.bokiVoiceResume)return;b.bokiVoiceResume=false;const clip=beforeStoryBokiCombatVoices[b.bokiVoiceIndex];if(clip&&!clip.ended){clip.muted=muted;clip.play()?.catch(()=>{if(beforeStoryScene?.unionCrown===b)b.bokiVoiceFailed=true;});}}
function updateBokiCombatLips(){
 const b=beforeStoryScene?.unionCrown,m=b?.enemyMouth;if(!b||!m||b.successor)return;
 const clip=beforeStoryBokiCombatVoices[b.bokiVoiceIndex];let level=0;
 if(clip){clip.muted=muted;if(!b.paused&&!b.ended){
  if(b.bokiVoiceFailed||clip.error){const beat=b.time-b.bokiQuoteStarted,word=b.bokiSpeech?.words.find(w=>beat>=w.start&&beat<w.end);if(word){const phase=(beat-word.start)/(word.end-word.start);level=.6*Math.abs(Math.sin(phase*Math.PI*word.syllables));}}
  else if(!clip.paused&&!clip.ended&&clip.readyState>=2){const data=BEFORE_STORY_BOKI_COMBAT_ENVELOPES[b.bokiVoiceIndex],frame=clip.currentTime/data.step,index=Math.floor(frame),mix=frame-index;level=(data.levels[index]||0)*(1-mix)+(data.levels[index+1]||0)*mix;}
 }}
 m.open.visible=level>.035;m.open.scale.set(m.width*(1-.12*level),.006+level*.028,.009);m.closed.visible=!m.open.visible;
}

